uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float amzp_dotSize;
uniform float amzp_spacing;
uniform float amzp_angle;
uniform float amzp_progress;
uniform float amzp_scale;
uniform float amzp_ellipse;
uniform float amzp_ellipseX;
uniform float amzp_ellipseY;
layout(color) uniform half4 amzp_primaryColor;
layout(color) uniform half4 amzp_secondaryColor;
uniform float amzp_colorMode;
uniform float amzp_contrast;
uniform float amzp_brightness;
uniform float amzp_edgeSoft;
uniform float amzp_useDisplacement;
uniform float amzp_dispAmount;
uniform float amzp_dispThreshold;
uniform float amzp_dispInvert;
uniform float amzp_dispSoft;
uniform float amzp_edgesHalftone;
uniform float amzp_edgeThreshold;
uniform float amzp_edgeBlur;
uniform float amzp_edgeStrength;
uniform float amzp_overlay;
uniform float amzp_blend;


    float2 getResolution(){
      float2 s = getTexSize((screen.zw/1.0));
      if (s.x <= 0.0 || s.y <= 0.0) s = float2(1920.0, 1080.0);
      return s;
    }
    float2 rot(float2 p, float a){
      float c = cos(a);
      float s = sin(a);
      return float2(p.x * c - p.y * s, p.x * s + p.y * c);
    }
    float applyToneF(float v, float amzp_contrast, float amzp_brightness){
      v = (v - 0.5) * amzp_contrast + 0.5 + amzp_brightness;
      return clamp(v, 0.0, 1.0);
    }
    float colorDist(float3 a, float3 b){ return length(a - b); }


    float sobelEdge(float2 uv, float2 px){

      float tl = dot(amzTexture(0, clamp(uv + float2(-px.x, -px.y), float2(0.0), float2(1.0))).rgb, float3(0.2126,0.7152,0.0722));
      float  l = dot(amzTexture(0, clamp(uv + float2(0.0, -px.y), float2(0.0), float2(1.0))).rgb, float3(0.2126,0.7152,0.0722));
      float tr = dot(amzTexture(0, clamp(uv + float2(px.x, -px.y), float2(0.0), float2(1.0))).rgb, float3(0.2126,0.7152,0.0722));
      float ml = dot(amzTexture(0, clamp(uv + float2(-px.x, 0.0), float2(0.0), float2(1.0))).rgb, float3(0.2126,0.7152,0.0722));
      float mm = dot(amzTexture(0, clamp(uv, float2(0.0), float2(1.0))).rgb, float3(0.2126,0.7152,0.0722));
      float mr = dot(amzTexture(0, clamp(uv + float2(px.x, 0.0), float2(0.0), float2(1.0))).rgb, float3(0.2126,0.7152,0.0722));
      float bl = dot(amzTexture(0, clamp(uv + float2(-px.x, px.y), float2(0.0), float2(1.0))).rgb, float3(0.2126,0.7152,0.0722));
      float  b = dot(amzTexture(0, clamp(uv + float2(0.0, px.y), float2(0.0), float2(1.0))).rgb, float3(0.2126,0.7152,0.0722));
      float br = dot(amzTexture(0, clamp(uv + float2(px.x, px.y), float2(0.0), float2(1.0))).rgb, float3(0.2126,0.7152,0.0722));


      float gx = -tl - 2.0*ml - bl + tr + 2.0*mr + br;
      float gy = -tl - 2.0*l - tr + bl + 2.0*b + br;
      return length(float2(gx, gy));
    }


    float blurMask(float2 uv, float2 px, float radius){

      float s = 0.0;
      float count = 0.0;
      int r = int(max(0.0, floor(radius)));
      for(int y = -r; y <= r; y++){
        for(int x = -r; x <= r; x++){
          float2 off = float2(float(x) * px.x, float(y) * px.y);
          s += sobelEdge(clamp(uv + off, float2(0.0), float2(1.0)), px);
          count += 1.0;
        }
      }
      return s / max(1.0, count);
    }

    void amzRender(){
      float2 res = getResolution();
      float2 uv = amzScreenNorm();
      float2 frag = uv * res;
      float2 center = 0.5 * res;
      float2 px = float2(1.0 / res.x, 1.0 / res.y);


      float dSize = max(1.0, amzp_dotSize);
      float dSpacing = max(1.0, amzp_spacing);
      float angDeg = amzp_angle;
      float rotAngle = radians(angDeg) + amzp_progress * 6.2831853;
      float s = amzp_scale;
      float edgeSoftness = max(0.001, amzp_edgeSoft);
      float cont = max(0.0, amzp_contrast);
      float bright = amzp_brightness;
      bool useSampleColor = (amzp_colorMode>0.5);
      bool useEllipse = (amzp_ellipse>0.5);
      float eX = max(0.001, amzp_ellipseX);
      float eY = max(0.001, amzp_ellipseY);

      float blendOut = clamp(amzp_blend, 0.0, 1.0);


      bool doDisp = (amzp_useDisplacement>0.5);
      float dispAmountPx = amzp_dispAmount;
      float dispThresholdVal = clamp(amzp_dispThreshold, 0.0, 1.0);
      bool dispInv = (amzp_dispInvert>0.5);
      float amzp_dispSoft = max(0.0, amzp_dispSoft);


      float3 colPrimary = amzp_primaryColor.rgb;
      float3 colSecondary = amzp_secondaryColor.rgb;


      bool onlyEdges = (amzp_edgesHalftone>0.5);
      float eThresh = clamp(amzp_edgeThreshold, 0.0, 1.0);
      float eBlur = max(0.0, amzp_edgeBlur);
      float eStr = max(0.0, amzp_edgeStrength);


      float2 local = frag - center;
      local = rot(local, rotAngle);
      float2 rotPos = local + center;


      float2 cell = floor(rotPos / dSpacing);
      float2 cellCenterPx = (cell + 0.5) * dSpacing;


      float2 sampleUV = clamp(cellCenterPx / res, float2(0.0), float2(1.0));
      float3 sampleColor = amzTexture(0, sampleUV).rgb;
      float lum = dot(sampleColor, float3(0.2126, 0.7152, 0.0722));
      lum = applyToneF(lum, cont, bright);


      float inv = 1.0 - lum;
      float baseRadius = clamp((dSize * s) * 0.5 / dSpacing, 0.0, 0.5);
      float radius = baseRadius * inv;


      float dx = (rotPos.x - cellCenterPx.x);
      float dy = (rotPos.y - cellCenterPx.y);
      if (useEllipse){
        dx /= eX;
        dy /= eY;
      }
      float dist = length(float2(dx, dy));
      float pxRadius = radius * dSpacing;
      float edge = max(1.0, dSpacing * 0.01) * edgeSoftness;
      float alphaDot = 1.0 - smoothstep(pxRadius - edge, pxRadius + edge, dist);


      float primaryMatch = 1.0 - smoothstep(dispThresholdVal, dispThresholdVal + 0.2, colorDist(sampleColor, colPrimary));
      float3 dotCol;
      if (useSampleColor){
        dotCol = sampleColor;
      } else {
        dotCol = mix(colSecondary, colPrimary, primaryMatch);
      }


      float match = 1.0 - smoothstep(dispThresholdVal, dispThresholdVal + 0.25, colorDist(sampleColor, colPrimary));
      match = pow(match, 1.0 + amzp_dispSoft * 2.0);
      float2 dir = normalize(float2(rotPos.x - cellCenterPx.x, rotPos.y - cellCenterPx.y) + float2(1e-6, 0.0));
      if (length(float2(rotPos.x - cellCenterPx.x, rotPos.y - cellCenterPx.y)) < 0.5){
        dir = float2(0.0, -1.0);
      }
      float sign = dispInv ? -1.0 : 1.0;
      float2 dispUVoffset = sign * dir * (match * dispAmountPx) / res.y;
      float2 displacedUV = clamp(uv + dispUVoffset, float2(0.0), float2(1.0));
      float3 displacedBackground = amzTexture(0, displacedUV).rgb;


      float3 finalDotCol;
      if (useSampleColor){
        finalDotCol = sampleColor * (0.3 + 0.7 * (1.0 - lum));
      } else {
        finalDotCol = dotCol;
      }
      float3 halftone = finalDotCol * alphaDot;


      float e = sobelEdge(uv, px);        
      if (eBlur > 0.5){

        float b = blurMask(uv, px, eBlur);
        e = mix(e, b, 0.6);
      }

      float eMask = smoothstep(eThresh, eThresh + 0.25 * max(0.001, eBlur), e) * eStr;
      eMask = clamp(eMask, 0.0, 1.0);


      float3 baseBg = doDisp ? displacedBackground : amzTexture(0, uv).rgb;



      float finalDotMix = alphaDot * blendOut;
      if (onlyEdges){
        finalDotMix *= eMask;
      }

      float3 outCol;
      if ((amzp_overlay>0.5)){
        outCol = mix(baseBg, halftone, finalDotMix);
      } else {
        float3 original = amzTexture(0, uv).rgb;

        if (onlyEdges){
          outCol = mix(original, mix(baseBg, halftone, finalDotMix), blendOut);
        } else {
          outCol = mix(original, halftone, blendOut);
        }
      }

      amzOutput = float4(outCol, 1.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

