      if (useSampleColor){
        finalDotCol = sampleColor * (0.3 + 0.7 * (1.0 - lum));
      } else {
        finalDotCol = dotCol;
      }
      float3 halftone = finalDotCol * alphaDot;


      float e = sobelEdge(uv, px);        
      if (eBlur > 0.5){

        float b = blurMask(uv, px, eBlur);
        e = mix(e, b, 0.6);
      }

      float eMask = smoothstep(eThresh, eThresh + 0.25 * max(0.001, eBlur), e) * eStr;
      eMask = clamp(eMask, 0.0, 1.0);


      float3 baseBg = doDisp ? displacedBackground : amzTexture(0, uv).rgb;



      float finalDotMix = alphaDot * blendOut;
      if (onlyEdges){
        finalDotMix *= eMask;
      }

      float3 outCol;
      if ((amzp_overlay>0.5)){
        outCol = mix(baseBg, halftone, finalDotMix);
      } else {
        float3 original = amzTexture(0, uv).rgb;

        if (onlyEdges){
          outCol = mix(original, mix(baseBg, halftone, finalDotMix), blendOut);
        } else {
          outCol = mix(original, halftone, blendOut);
        }
      }

      amzOutput = float4(outCol, 1.0);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
